(function(){try{var a=typeof window<"u"?window:typeof global<"u"?global:typeof globalThis<"u"?globalThis:typeof self<"u"?self:{},n=new a.Error().stack;n&&(a._sentryDebugIds=a._sentryDebugIds||{},a._sentryDebugIds[n]="95c29cf9-15a2-4e43-a68b-07a96c9012ed",a._sentryDebugIdIdentifier="sentry-dbid-95c29cf9-15a2-4e43-a68b-07a96c9012ed")}catch{}})();var e={p3:"Kebersamaan",p4:"Kesetaraan",p1:"Prinsip hidup berdampingan:",p2:"Saling menghormati"},i={p1:"Perilaku yang diharapkan:",p2:"Perlakukan semua anggota dengan hormat.",p3:"Masukan yang membangun sangat kami hargai.",p4:"Semua ini tentang musik, jadi mari jaga agar komentar dan konten kita tetap terkait dengan musik saja.",p5:"Perlakukan orang lain sebagaimana Anda ingin diperlakukan."},t="Kode Etik Komunitas",k={p1:"Kita semua mencintai musik! Seperti komunitas lainnya, kita memiliki kode etik untuk menjaga harmoni dan suasana yang positif, serta memastikan semua orang merasa nyaman di sini. Mari kita bangun lingkungan yang ramah dan menginspirasi kita untuk berkarya."},m={p1:"Perilaku yang tidak dapat diterima (kami dapat menghapus akun Anda tanpa peringatan):",p2:"Memperlakukan sesama kreator dengan tidak hormat atau menyinggung.",p3:"Spam.",p4:"Membagikan konten seksual.",p5:"Membuat komentar yang bertujuan merendahkan, menyinggung, atau mengganggu anggota komunitas mana pun."},r={p1:"Tindakan yang dilakukan secara terbuka:"},u={p1:"Alasan untuk langsung diblokir:",p2:"Membagikan konten seksual dalam bentuk apa pun (gambar, komentar, dll.).",p3:"Membagikan konten atau membuat komentar yang mendorong kekerasan, rasisme, xenofobia, homofobia, seksisme, dan sejenisnya.",p4:"Mengirim spam kepada orang lain."},d={p1:"Jenis perilaku lain yang tidak dapat diterima:",p2:"Menghina atau memposting komentar yang merendahkan anggota komunitas mana pun:",p3:"Pelanggaran pertama: kami akan menonaktifkan akses Anda untuk berkomentar hingga pemberitahuan lebih lanjut.",p4:"Pelanggaran kedua: kami akan menonaktifkan kemampuan berkomentar secara permanen, atau menghapus akun Anda.",p5:"Spam ke saluran dukungan:",p6:"Tim dukungan kami akan selalu siap membantu Anda selama Anda menghubungi kami dengan sopan dan hanya terkait dengan platform kami. Sikap tidak sopan atau bersifat spam tidak diterima dan dapat berakibat penghapusan akun Anda."},s={p1:"Apa yang dimaksud dengan komentar yang tidak sopan?",p2:"Jenis komentar ini biasanya tidak relevan, tidak pantas, merugikan, atau sekadar mengganggu. Penulisnya tidak menulis dengan itikad baik, dan komentar tersebut dimaksudkan untuk membuat orang lain merasa buruk atau terhina.",p3:"Jika Anda tidak yakin apakah komentar Anda tidak sopan atau tidak, hindari memublikasikannya dan carilah cara yang santun dan beradab untuk menyampaikan pendapat."},p={s2:e,s3:i,title:t,s1:k,s4:m,s5:r,s6:u,s7:d,s8:s};export{p as default,k as s1,e as s2,i as s3,m as s4,r as s5,u as s6,d as s7,s as s8,t as title};

